  let size = max(nsh.size, vec2f(1.0));
  let grain = hash(uv * nsh.size * max(nsh.scale, 1.0)) - 0.5;
  let px = 1.0 / max(nsh.scale, 1.0);
  let top = smoothstep(px, 0.0, uv.y * size.y);

